/bin/bash -lc "set +e
for pair in \\
  'bing https://www.bing.com/search?q=%22Government+College+Bhanpura%22+official+website' \\
  'ddg https://html.duckduckgo.com/html/?q=%22Government+College+Bhanpura%22+official+website' \\
  'brave https://search.brave.com/search?q=%22Government+College+Bhanpura%22+official+website'; do
  name="'${pair%% *}; url=${pair#* };
  curl --insecure -fsSL --max-time 30 -A '"'Mozilla/5.0' \""'$url" -o "$TMPDIR/search_bhanpura_${name}.html";
  code=$?; echo "$name code=$code bytes=$(wc -c < "$TMPDIR/search_bhanpura_${name}.html" 2>/dev/null || true)";
done
for f in "$TMPDIR/search_bhanpura_bing.html" "$TMPDIR/search_bhanpura_ddg.html" "$TMPDIR/search_bhanpura_brave.html"; do [ -s "$f" ] || continue; echo "FILE=$f"; rg -io '"'https?["'^"<> ]+|government college[''^<]{0,180}|bhanpura[''^<]{0,180}'"' \""'$f" | head -80; done'

