/bin/bash -lc "set +e
urls=(
  'https://search.yahoo.com/search?p=%22Government+College+Bhanpura%22+Mandsaur'
  'https://www.ecosia.org/search?q=%22Government+College+Bhanpura%22+Mandsaur'
  'https://www.startpage.com/sp/search?query=%22Government+College+Bhanpura%22+Mandsaur'
  'https://www.mojeek.com/search?q=%22Government+College+Bhanpura%22+Mandsaur'
)
names=(yahoo ecosia startpage mojeek)
for idx in "'${!urls[@]}; do
  name=${names[$idx]}; url=${urls[$idx]};
  curl --insecure -fsSL --max-time 25 -A '"'Mozilla/5.0' \""'$url" -o "$TMPDIR/search_bhanpura_$name.html";
  code=$?; echo "$name code=$code bytes=$(wc -c < "$TMPDIR/search_bhanpura_$name.html" 2>/dev/null || true)";
  if [ -s "$TMPDIR/search_bhanpura_$name.html" ]; then
    echo "-- $name matches --"; sed '"'s/></>\\n</g' \""'$TMPDIR/search_bhanpura_$name.html" | rg -i '"'bhanpura|government college|<h[123]|result' | head -45;
  fi
done"

